func seedListMemosBenchmarkData(ctx context.Context, stores *store.Store, hostUser *store.User) (string, error) {
	topLevelMemos := make([]*store.Memo, 0, benchmarkTopLevelMemoCount)
	commentParentName := ""

	for i := 0; i < benchmarkTopLevelMemoCount; i++ {
		visibility := store.Private
		if i%4 == 0 {
			visibility = store.Public
		}
		memo, err := stores.CreateMemo(ctx, &store.Memo{
			UID:        fmt.Sprintf("memo-%06d", i),
			CreatorID:  hostUser.ID,
			Content:    benchmarkMemoContent(i),
			Visibility: visibility,
		})
		if err != nil {
			return "", err
		}
		topLevelMemos = append(topLevelMemos, memo)

		if i%3 == 0 {
			if _, err := stores.CreateAttachment(ctx, &store.Attachment{
				UID:       fmt.Sprintf("att-%06d", i),
				CreatorID: hostUser.ID,
				Filename:  fmt.Sprintf("memo-%06d.png", i),
				Type:      "image/png",
				Size:      2048,
				MemoID:    &memo.ID,
			}); err != nil {
				return "", err
			}
		}

		if i%5 == 0 {
			if _, err := stores.UpsertReaction(ctx, &store.Reaction{
				CreatorID:    hostUser.ID,
				ContentID:    "memos/" + memo.UID,
				ReactionType: "thumbs-up",
			}); err != nil {
				return "", err
			}
		}
	}

	for i, memo := range topLevelMemos {
		if i+1 < len(topLevelMemos) && i%4 == 0 {
			if _, err := stores.UpsertMemoRelation(ctx, &store.MemoRelation{
				MemoID:        memo.ID,
				RelatedMemoID: topLevelMemos[i+1].ID,
				Type:          store.MemoRelationReference,
			}); err != nil {
				return "", err
			}
		}

		if i%6 == 0 {
			commentMemo, err := stores.CreateMemo(ctx, &store.Memo{
				UID:        fmt.Sprintf("comment-%06d", i),
				CreatorID:  hostUser.ID,
				Content:    fmt.Sprintf("Comment for memo %06d", i),
				Visibility: store.Private,
			})
			if err != nil {
				return "", err
			}
			if _, err := stores.UpsertMemoRelation(ctx, &store.MemoRelation{
				MemoID:        commentMemo.ID,
				RelatedMemoID: memo.ID,
				Type:          store.MemoRelationComment,
			}); err != nil {
				return "", err
			}
			if commentParentName == "" {
				commentParentName = "memos/" + memo.UID
			}
		}
	}

	return commentParentName, nil
}

func TestProtectedMethodsRequireAuth(t *testing.T) {
	protectedMethods := []string{
		// Auth Service - logout and get current user require auth
		"/memos.api.v1.AuthService/SignOut",
		"/memos.api.v1.AuthService/GetCurrentUser",
		// Instance Service - admin operations
		"/memos.api.v1.InstanceService/UpdateInstanceSetting",
		"/memos.api.v1.InstanceService/TestInstanceEmailSetting",
		// User Service - modification operations
		"/memos.api.v1.UserService/ListUsers",
		"/memos.api.v1.UserService/UpdateUser",
		"/memos.api.v1.UserService/DeleteUser",
		// Memo Service - write operations
		"/memos.api.v1.MemoService/CreateMemo",
		"/memos.api.v1.MemoService/UpdateMemo",
		"/memos.api.v1.MemoService/DeleteMemo",
		// Attachment Service - write operations
		"/memos.api.v1.AttachmentService/CreateAttachment",
		"/memos.api.v1.AttachmentService/DeleteAttachment",
		// Shortcut Service
		"/memos.api.v1.ShortcutService/CreateShortcut",
		"/memos.api.v1.ShortcutService/ListShortcuts",
		"/memos.api.v1.ShortcutService/UpdateShortcut",
		"/memos.api.v1.ShortcutService/DeleteShortcut",
	}

	for _, method := range protectedMethods {
		t.Run(method, func(t *testing.T) {
			assert.False(t, IsPublicMethod(method), "Expected %s to require auth", method)
		})
	}
}

func TestAuthorizerCheckAccess(t *testing.T) {
	ctx := context.Background()
	authenticated := &auth.AuthResult{AccessToken: "token"}

	openInstance := &Authorizer{profile: &profile.Profile{InstanceURL: "https://memos.example.com"}}
	privateInstance := &Authorizer{profile: &profile.Profile{InstanceURL: ""}}

	const (
		protectedMethod = "/memos.api.v1.MemoService/CreateMemo"
		publicMethod    = "/memos.api.v1.MemoService/ListMemos"
		bootstrapMethod = "/memos.api.v1.AuthService/SignIn"
		shareMethod     = "/memos.api.v1.MemoService/GetMemoByShare"
	)

	cases := []struct {
		name      string
		az        *Authorizer
		procedure string
		result    *auth.AuthResult
		wantErr   bool
	}{
		{"authenticated reaches protected method", privateInstance, protectedMethod, authenticated, false},
		{"authenticated reaches public method on private instance", privateInstance, publicMethod, authenticated, false},
		{"anonymous denied on protected method", openInstance, protectedMethod, nil, true},
		{"anonymous allowed on public method, open instance", openInstance, publicMethod, nil, false},
		{"anonymous denied on public method, private instance", privateInstance, publicMethod, nil, true},
		{"anonymous allowed on bootstrap method, private instance", privateInstance, bootstrapMethod, nil, false},
		{"anonymous allowed on share access, private instance", privateInstance, shareMethod, nil, false},
	}
